import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`video-storyboard`,heroTitle:`Create video storyboards in minutes`,heroSubtitle:`Perplexity Computer analyzes your brand, scripts scene-by-scene storyboards, and delivers shoot-ready visual plans — automatically.`,inputUrlCta:`Storyboard my video`,inputUrlPlaceholder:`yourbrand.com`,inputUrlPrefill:`Go to {url} and perform a deep brand and content analysis — extract the brand voice, visual style, color palette, target audience, key products or services, and messaging pillars. Then create a complete video storyboard package: 1) Recommend 3 video concepts tailored to the brand's goals (product demo, brand story, social ad) with a one-line pitch for each. 2) For the top concept, build a full scene-by-scene storyboard with 8-12 frames — each frame should include a visual description, camera angle/movement, on-screen text or dialogue, voiceover script, and estimated duration. 3) Include a shot list with locations, talent needs, and props for each scene. 4) Provide a mood board section referencing the brand's visual style — colors, typography, and image direction for each frame. 5) Add format variations — adapt the storyboard for a 60-second hero video, a 30-second cutdown, and a 15-second social clip. 6) Deliver everything in a structured document with a production timeline and checklist.`,heroOverlaySteps:[`Analyzing your brand voice, visuals, and messaging`,`Scripting scene-by-scene storyboard frames with shot direction`,`Building format variations for hero, cutdown, and social clips`,`Complete storyboard with shot list and production plan — ready to shoot`],generatingSteps:[`Visiting {url} to extract brand voice, visual style, and key messaging`,`Designing an agent to script scene-by-scene storyboards with camera direction and dialogue`,`Configuring format variations for 60s, 30s, and 15s video cuts`,`Setting up shot lists, mood boards, and production timelines`],featureSectionTitle:`From URL to shoot-ready storyboard`,featureCardTitles:[`Connects to your creative stack`,`Outputs you can shoot`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, Canva, Slack — Computer delivers storyboards, shot lists, and mood boards straight into the tools your team already uses.`,`Scene-by-scene storyboard frames. Camera angles and movement notes. Voiceover scripts. Shot lists with talent and props. Format variations for every platform.`],capabilitySectionTitle:`Your video producer, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a shoot-ready storyboard.`,capabilityCards:[{title:`Brand Analysis`,description:`Computer can study your website — voice, colors, typography, audience, and messaging — to ensure every frame matches your brand identity.`},{title:`Concept Development`,description:`Computer can generate multiple video concepts — product demos, brand stories, social ads — tailored to your goals and audience.`},{title:`Scene-by-Scene Frames`,description:`Computer can script 8-12 storyboard frames with visual descriptions, camera direction, dialogue, voiceover, and timing for each scene.`},{title:`Connect Your Tools`,description:`Computer can push storyboards into Google Docs, Notion, Canva, and Google Drive — build workflows across your entire creative production stack.`},{title:`Remember & Learn`,description:`Computer can remember your brand guidelines, past storyboards, and top-performing videos — so every new concept builds on what works.`},{title:`Monitor & Update`,description:`Computer can watch your website for new products, campaigns, or messaging shifts — and flag when storyboards need refreshing.`}]});export{t as default};
